// Generated by scripts/build-lesson-bundles.cjs.
((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
'use strict';

globalThis.makeMedvezhonokEdition = function (year, grade, rows, material = {}) {
  const letters = 'АБВГД';
  const plain = value => value.replace(/<\/?(?:em|strong|u)>/g, '');
  const escape = value => value.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(({author, question, choices, key, review, figure, unrated, points}, index) => {
    const [title, idea, check] = review;
    const answer = letters.indexOf(key);
    const textChoices = choices.map(plain);
    const options = figure?.options?.map(({src, description, pixelWidth, pixelHeight}, i) => ({
      image: src, description, pixelWidth, pixelHeight, text: figure.onlyPictures ? '' : textChoices[i],
    })) ?? textChoices.map(text => ({text}));
    return {
      number: index + 1, title, author, question: plain(question), choices: textChoices,
      ...(plain(question) !== question ? {formattedQuestion: question} : {}),
      ...(textChoices.some((value,i) => value !== choices[i]) ? {formattedChoices: choices} : {}),
      ...(unrated ? {questionNote: unrated, archiveAnswer: key} : {}),
      ...(figure ? {
        choiceLayout: {options, condition: figure.condition},
        choiceImages: options.map(option => option.image),
        ...(figure.condition ? {conditionImage: figure.condition.src, conditionAlt: figure.condition.alt} : {}),
      } : {}),
      answer: unrated ? null : answer, points: points ?? (index < 10 ? 3 : index < 20 ? 4 : 5),
      skill: 'Русский медвежонок · Языкознание', hideIntroText: true, showCompletedStep: true,
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ['Первый шаг', 'Рассуждение', idea],
        ['Проверка', 'Проверка', check],
        ['Ответ', unrated ? 'Ответ в архивном ключе' : 'Ответ', ''],
      ],
    };
  });
  const scenes = rows.map(({review, key}, i) => {
    const terms = review.slice(1).map(step => [...new Set(
      Array.from(step.matchAll(/«([^«»\n]{1,44})»/gu), match => match[1])
    )].slice(0, 5));
    return (step, frame) => {
      if (!step) return '';
      const result = lessons[i].choices[letters.indexOf(key)].replace(/^\[(.*)\][.]?$/, '$1');
      const tokens = step === 3 ? [key + (result ? ' · ' + result : '')] : terms[step-1];
      if (step < 3 && tokens.length < 2) return '';
      return '<div class="word-scene" data-result="' + (step === 3) + '">' + tokens.map((token, index) => {
        const reveal = Math.min(1, Math.max(0, (frame - index * 0.65) / 0.42));
        return '<span class="word-token" style="--reveal:' + reveal.toFixed(3) + '">' + escape(token) + '</span>';
      }).join('') + '</div>';
    };
  });
  const reviewedKey = rows.some(row => row.reviewedEdition);
  return {
    id: year + '-medvezhonok-' + grade, year, grades, subject: 'ru',
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы'),
    sources: {
      contest: 'Русский медвежонок',
      tasksUrl: 'assets/medvezhonok/' + year + '/' + (material.tasksFile ?? grade + '.pdf'),
      reviewedKey,
      answersUrl: 'assets/medvezhonok/' + year + '/' + (material.answersFile ?? (reviewedKey ? 'reviewed-' + grade : grade + '-answers') + '.pdf'),
      ...(material.solutionsFile ? {solutionUrl: 'assets/medvezhonok/' + year + '/' + material.solutionsFile} : {}),
      ...(year === 2004 && grade === '2-3' ? {solutionUrl: 'assets/medvezhonok/2004/2-3-answers.pdf'} : {}),
    },
    lessons, scenes,
  };
};

register(globalThis.makeMedvezhonokEdition(2021, "6-7", [{"author":"П. Аркадьев","question":"Со мной _____ ужасная история.","choices":["переключилась","преключилась","приключилась","заключилась","злоключилась"],"key":"В","review":["Что случилось с героем","О событии, которое произошло с человеком, часто говорят «со мной приключилось». От того же корня слово «приключение».","Вставляем «приключилась ужасная история». «Переключилась» описывает смену режима или внимания."]},{"author":"И. Рубанов","question":"Смысл какой из этих фраз сильно изменится, если в ней заменить слово <em>любой</em> словом <em>каждый</em> (в соответствующей форме)?","choices":["Любое дело порядок любит.","Принять гостей была готова любая семья в посёлке.","Тебе нужно выиграть любую из трёх партий.","К любой из этих проблем можно подойти с двух сторон.","Это доказательство сложное, его не любой поймёт"],"key":"В","review":["Любой и каждый","«Любой» может значить «всё равно какой». «Каждый» требует проверить всех членов группы по отдельности.","Условие В сначала разрешает выиграть одну из трёх партий на выбор. Выиграть «каждую из трёх» означает выиграть все три."]},{"author":"И. Рубанов","question":"Андрей раздобрел. Бориса задобрили. Виктора одобрили. Григорий подобрел. Кто из них, судя по сказанному, точно стал добрее к людям?","choices":["Андрей","Борис","Виктор","Григорий","никто"],"key":"Г","review":["Кто стал добрее","«Раздобрел» может означать, что человек располнел. «Задобрили» — добились благосклонности, «одобрили» — признали хорошим его поступок.","«Подобрел» значит стал добрее. Из фраз только в последней прямо сказано об изменении характера."]},{"author":"И. Рубанов","question":"В каком из этих слов -фон не означает то, что в остальных?","choices":["саксофон","марафон","мегафон","микрофон","телефон"],"key":"Б","review":["Слова с «фон»","Саксофон, мегафон, микрофон и телефон связаны со звучанием. В них часть -фон восходит к слову, обозначавшему голос или звук.","«Марафон» назван по местности Марафон в Греции. Здесь последние буквы не имеют значения «звук»."]},{"author":"С. Переверзева","question":"Даны фразы из рассказа Леонида Пантелеева «Буква „ты“». В какой из них можно переставить запятую в другое место — и смысл почти не изменится?","choices":["Наверное, мы, голубушка, с тобой немного переучились.","Внутри у меня уже всё кипело, как вода в чайнике.","Ей, наверно, было стыдно, что она такая бестолковая.","Нет, уж сейчас мы на эту удочку не попадёмся.","Конечно, не очень-то хорошо говорить неправду"],"key":"Г","review":["Запятая в реплике","«Нет» и «уж» могут вместе образовывать начало отказа. Сравним, как меняется граница между словами с запятой.","Можно сказать «Нет уж, сейчас мы на эту удочку не попадёмся». Как и в исходной реплике, говорящий отказывается снова поддаваться на уловку."]},{"author":"А. Сомин","question":"Какое из этих слов по смыслу лишнее?","choices":["сослуживец","соавтор","соплеменник","советник","совладелец"],"key":"Г","review":["Значение начала «со-»","Сослуживец служит вместе с кем-то, соавтор вместе пишет, соплеменник принадлежит к тому же племени, совладелец владеет чем-то совместно.","Советник даёт советы. Начальное «со» входит в слово «совет», и смысл совместности здесь не выражен."]},{"author":"И. Рубанов","question":"В каком из этих выражений глагол почистить употребляется совсем не так, как в остальных?","choices":["почистить ковёр","почистить снег","почистить зубы","почистить брюки","почистить дорожку"],"key":"Б","review":["Что делают со снегом","При чистке ковра, зубов, брюк или дорожки очищают то, что названо после глагола.","Когда говорят «почистить снег», снег убирают. Им была покрыта поверхность, которую хотят очистить."]},{"author":"Е. Муравенко","question":"Хор — это ансамбль или группа певцов, а хорь — небольшой пушной зверёк. В каком падеже существительные хор и хорь пишутся одинаково?","choices":["в родительном","в дательном","в винительном","в творительном","в предложном"],"key":"Д","review":["Два слова в одном падеже","Склоняем оба слова. В родительном получится «хора» и «хоря», в дательном — «хору» и «хорю», в творительном — «хором» и «хорём».","В винительном будут «хор» и «хоря». Только в предложном обе формы имеют один вид: «о хоре»."]},{"author":"Л. Фёдорова","question":"Для какого из слов соответствующее однокоренное название лица женского пола образуется иначе, чем для остальных?","choices":["дворянин","барин","армянин","марсианин","инопланетянин"],"key":"Б","review":["Названия женщин","От «дворянин», «армянин», «марсианин» и «инопланетянин» получаются «дворянка», «армянка», «марсианка» и «инопланетянка».","К слову «барин» соответствует «барыня». Оно образовано без суффикса -к-, в отличие от четырёх остальных."]},{"author":"М. Мирошниченко","question":"С мальчиком Костей Журавлёвым часто проводят воспитательные беседы, и он заметил, что в этих беседах звучит много названий птиц. Про него говорят, что он пишет как _____ лапой, на уроках считает _____, при виде трудностей прячет голову в песок как _____, но ему всё как с _____ вода. Какую птицу не упоминают в беседах с Костей?","choices":["лебедя","гуся","курицу","страуса","ворону"],"key":"А","review":["Птицы в выражениях","Неразборчиво пишут «как курица лапой», а отвлекающийся ученик «считает ворон».","Голову прячут «как страус», а о безразличном говорят «как с гуся вода». В этих фразах нет лебедя."]},{"author":"Е. Бикмаев","question":"Подберите глаголы к существительным клюв и клёв:","choices":["клювать и клёвать","клевать и клёвать","клювать и клевать","в обоих случаях одинаково: клевать","в обоих случаях одинаково: клювать"],"key":"Г","review":["Клюв и клёв","Птица ударяет клювом, когда клюёт зерно. Рыба клюёт, когда берёт наживку; активность рыбы называют клёвом.","Для обоих действий употребляется «клевать». Сравни формы «клюёт», «клевал» и слово «клёв»: гласная меняется внутри одного корня."]},{"author":"Е. Муравенко","question":"Даны слова лапоть, лепет, полёт и тополь. Какие два из них содержат одинаковый набор согласных звуков?","choices":["лапоть и лепет","лапоть и полёт","лепет и полёт","лепет и тополь","полёт и тополь"],"key":"Д","review":["Наборы согласных","Мягкость согласного важна. В «лапоть» мягкая Т, в «лепет» мягкие Л и П, поэтому эти слова не подходят.","В «полёт» и «тополь» согласные идут в разном порядке, но набор одинаков: твёрдые П и Т, мягкая Л."]},{"author":"И. Шаронов","question":"Какое из выражений совсем не похоже по смыслу на другие?","choices":["раз, два и обчёлся","с гулькин нос","кот наплакал","не бог весть сколько","куры не клюют"],"key":"Д","review":["Сколько это","«Раз, два и обчёлся», «с гулькин нос», «кот наплакал» и «не бог весть сколько» говорят, когда чего-то мало.","«Куры не клюют» указывает на изобилие, чаще всего денег. Значение противоположное."]},{"author":"И. Рубанов","question":"Маленький мальчик узнал, что цемент делают на цементном заводе, и поэтому решил, что: 1) бетон делают на бетонном заводе, 2) кирпич делают на кирпичном заводе, 3) сахар делают на сахарном заводе, 4) мороженое делают на мороженом заводе. Какое из этих утверждений точно неправильное?","choices":["первое","второе","третье","четвёртое","все четыре утверждения правильные"],"key":"Г","review":["Что производят на заводе","Прилагательные «цементный», «бетонный», «кирпичный» и «сахарный» могут называть предприятие по его продукции.","«Мороженый» означает замёрзший или замороженный. «Мороженый завод» — замёрзшее здание, а предприятие по производству мороженого можно назвать фабрикой мороженого."]},{"author":"И. Иткин","question":"В 1921 г. поэт Велимир Хлебников совершил поездку в одну из зарубежных стран. Об этой поездке он написал поэму __________.","choices":["«Вода без Вэ»","«Дорога без Дэ»","«Париж без Пэ»","«Тиран без Тэ»","«Уступы без У»"],"key":"Г","review":["Название поэмы","В каждом варианте предлагают убрать первую букву. Из «Тиран» без названной Т получается «Иран».","Хлебников ездил в Иран, который тогда называли также Персией. Поэтому поэма называется «Тиран без Тэ»."]},{"author":"С. Дьяченко","question":"Какое из этих слов может быть отнесено только к одной части речи?","choices":["кувырком","верхом","бегом","кругом","мельком"],"key":"Д","review":["Часть речи слова","«Кувырком», «верхом», «бегом» и «кругом» могут быть наречиями или творительными формами существительных «кувырок», «верх», «бег», «круг».","У «мельком» нет такого существительного. Это только наречие со значением «бегло, ненадолго»."]},{"author":"Л. Фёдорова","question":"Слово музыка в русском языке заимствованное. А как раньше называли музыку?","choices":["гульба","гудьба","гоньба","гурьба","голытьба"],"key":"Б","review":["Старинное название музыки","Сравним старые слова со звуками музыкальных инструментов. Сюда подходит корень гуд-, как в «гудеть» и «гудок».","«Гудьбой» называли игру на инструментах, музыку. «Гульба» и «гурьба» имеют другие значения."]},{"author":"С. Дьяченко","question":"Какое слово существенно отличается от остальных по смыслу?","choices":["размеры","объёмы","весы","сорта","параметры"],"key":"В","review":["Прибор или характеристика","Размер, объём, сорт и параметр могут быть характеристиками предмета или материала.","Весы — прибор, на котором определяют вес. Именно это слово называет инструмент."]},{"author":"О. Подлесская","question":"В какой паре есть несуществующее слово?","choices":["вобще — вообще","посредине — посередине","бобр — бобёр","наверно — наверное","вслед — вослед"],"key":"А","review":["Как пишется «вообще»","«Посредине» и «посередине», «наверно» и «наверное», «вслед» и «вослед» существуют. Есть также «бобр» и «бобёр».","Нормативное написание «вообще» — с двумя О. Форма «вобще» является ошибкой."]},{"author":"И. Рубанов","question":"1) Рабочие за глаза постоянно ругали слишком строгого хозяина.\n2) На эту работу недели хватит за глаза.\n3) Я полюбил её за глаза, весёлые и добрые.\n4) В глаза эта сплетница ничего не скажет, а за глаза все кости перемоет.\nВ каких двух фразах выражение за глаза означает одно и то же?","choices":["в первой и второй","во второй и третьей","в третьей и четвёртой","в четвёртой и первой","ни в каких"],"key":"Г","review":["Значения «за глаза»","В первой и четвёртой фразах человека обсуждают, когда он сам этого не слышит. Это переносное «в его отсутствие».","Во второй «хватит за глаза» означает «хватит с избытком». В третьей речь о настоящих глазах. Совпали первая и четвёртая фразы."]},{"author":"Б. Иомдин","question":"Четырёхлетний Яша: «Папа, помоги мне, я застрял! А, всё, ________». Последнее слово Яшиной реплики не существует в русском языке. А звучит так же, как слово, связанное с _____.","choices":["дверями","верёвками","норами","кроликами","пистолетами"],"key":"Д","review":["Слово маленького Яши","Яша застрял, а затем сам выбрался. По аналогии с «застрял» он мог придумать «выстрял», заменив за- на вы-.","По звучанию «выстрял» совпадает с «выстрел»: без ударения гласные после Р звучат одинаково. Выстрел связан с пистолетом."]},{"author":"Б. Иомдин","question":"С приставкой раз- этот глагол часто употребляется со словом война, с приставкой за- — со словом знакомство, а с приставкой пере- — со словом _____.","choices":["разговор","дорога","рана","язык","конфликт"],"key":"В","review":["Три приставки при глаголе","Войну можно «развязать», а знакомство «завязать». Общий глагол — «вязать».","С пере- получается «перевязать». Так говорят о ране, на которую накладывают повязку."]},{"author":"Б. Иомдин","question":"При переводе этих строк на латинский язык в четырёх случаях можно было бы использовать глагол videre, а в одном — глагол audire. В каком?","choices":["Мне другие мерещатся тени,\nМне другая поёт нищета. (А. Тарковский)","Всё мне мерещится поле с гречихою,\nВ маленьком доме сирень на окне. (Д. Кедрин)","В душистой тиши между царственных лип\nМне мачт корабельных мерещится скрип. (А. Ахматова)","За тусклым светом фонаря\nЕму мерещится заря. (А. Блок)","Мне мерещатся иссиня-чёрные косы,\nИзумруд удлинённых насмешливых глаз. (И. Северянин)"],"key":"В","review":["Видеть или слышать","Латинское videre значит «видеть», а audire — «слышать». Тени, поле, заря и косы в стихах относятся к зрению.","У Ахматовой мерещится скрип, то есть звук. Здесь нужен audire."]},{"author":"Б. Иомдин","question":"В команде Пли! когда-то был ещё гласный __.","choices":["а","о","у","и","ы"],"key":"А","review":["Старая команда","«Пли!» — команда открыть огонь. Полная исходная команда связана с глаголом «палить».","Она звучала «Пали!». В краткой форме исчезла гласная А."]},{"author":"Е. Муравенко","question":"Какой глагол образован не так, как остальные?","choices":["столярничать","плотничать","сотрудничать","посредничать","соперничать"],"key":"А","review":["Образование глаголов","«Плотничать», «сотрудничать», «посредничать», «соперничать» связаны с существительными «плотник», «сотрудник», «посредник», «соперник». Конечная К основы чередуется с Ч.","В «столяр» такого окончания основы нет. «Столярничать» образовано от «столяр» добавлением другой части, так что выделяется А."]},{"author":"И. Иткин","question":"В песне Александра Галича «Красный треугольник» тётя Паша, женщина малообразованная, говорит: «И племянница моя, Нина Саввовна, // Она думает как раз то же самое...». А как должно выглядеть женское отчество от имени Савва в соответствии с общими правилами русского языка?","choices":["именно так: Саввовна","Саввна","Саввовична","Саввинична","Саввична"],"key":"Д","review":["Отчество от имени Савва","Имя Савва оканчивается на -а. У него сохраняется основа Савв-, как в мужском отчестве Саввич.","Женская форма с -ична — «Саввична». «Саввовна» получилось бы по образцу других имён, и именно так персонаж песни ошибся."]},{"author":"М. Мирошниченко","question":"Мальчик Ваня, большой любитель разных книг, сделал досадную ошибку в контрольной работе: неправильно определил род слова. Как вы думаете, в каком слове ошибся Ваня?","choices":["голубь","журавль","снегирь","лебедь","гусь"],"key":"Г","review":["Род названий птиц","В современном языке «лебедь» — существительное мужского рода, как остальные названия из списка.","В сказках и старых стихах встречаются формы женского рода, например «лебедь белая». Привычка к такой форме могла запутать читателя."]},{"author":"О. Подлесская","question":"Перед вами — фрагмент из книги Алексея Толстого «Приключения Буратино, или Золотой ключик» издания 2013 года: Карабас тряс сосну. Буратино бросил в него сверху большие шишки. Одна шишка попала Карабасу в разинутый рот. В одно слово по сравнению с оригиналом закралась ошибка. В какое?","choices":["бросил","сверху","попала","Карабасу","разинутый"],"key":"А","review":["Сравниваем с оригиналом","У Толстого Буратино бросает шишки одну за другой, пока Карабас трясёт сосну. Затем одна шишка попадает в рот.","В оригинале стоит «бросал», то есть действие продолжалось. В задании его заменили словом «бросил»."]},{"author":"П. Аркадьев","question":"У каких из глаголов подогнуть, подобрать, подогнать, подгонять и подпереть во всех формах приставка содержит одинаковое число слогов?","choices":["только у подогнуть","только у подогнуть и подогнать","только у подогнуть и подпереть","только у подгонять","только у подогнуть и подгонять"],"key":"Д","review":["Слоги в приставках","Сравним «подобрать — подберу», «подогнать — подгоню», «подпереть — подопру». В этих парах под- чередуется с подо-, меняя число слогов.","У «подогнуть — подогну» всегда подо-, у «подгонять — подгоняю» всегда под-. Число слогов сохраняется только у этих двух."]},{"author":"И. Иткин и С. Переверзева","question":"Даны пары букв: И — Й, М — Ь, Т — Ъ. В каких из этих пар названия букв начинаются на одну и ту же букву?","choices":["во всех","М — Ь, Т — Ъ","И — Й, Т — Ъ","только Т — Ъ","ни в каких"],"key":"В","review":["С чего начинаются названия","«И» и «и краткое» начинаются на И. «Тэ» и «твёрдый знак» начинаются на Т.","В оставшейся паре названия «эм» и «мягкий знак» начинаются с разных букв. Подходят И — Й и Т — Ъ."]}], {"year":2021,"grade":"6-7","tasksFile":"6-7.pdf","answersFile":"6-7-answers.pdf","sourceUrl":"https://konkurs43.ru/rm/task2021-1.zip"}), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
